python3 -c "
import ifcopenshell

model = ifcopenshell.open('/filesystem/final_batch4__structural_task7_roof_deck_design__blind/15_model/DC2-A-STR_Roof_Structure_Model_RevC.ifc')

def get_placement_coord(elem):
    # Traverse ObjectPlacement
    plc = elem.ObjectPlacement
    coords = []
    while plc:
        if plc.is_a('IfcLocalPlacement'):
            rel = plc.RelativePlacement
            if rel and rel.is_a('IfcAxis2Placement3D'):
                loc = rel.Location.Coordinates
                coords.append(loc)
            plc = plc.PlacementRelTo
        else:
            break
    return coords

print('=== OPENINGS ===')
for op in model.by_type('IfcOpeningElement'):
    print(op.Name, op.Description, op.Tag)
    rep = op.Representation
    coords = get_placement_coord(op)
    print('  Placement coords:', coords)
    for pset in op.IsDefinedBy:
        if pset.is_a('IfcRelDefinesByProperties'):
            ps = pset.RelatingPropertyDefinition
            if ps.is_a('IfcPropertySet'):
                print('  Pset:', ps.Name, {p.Name: p.NominalValue.wrappedValue for p in ps.HasProperties if hasattr(p, 'NominalValue')})

print('\n=== PROXIES (OBSTRUCTIONS) ===')
for px in model.by_type('IfcBuildingElementProxy'):
    coords = get_placement_coord(px)
    ps_dict = {}
    for pset in px.IsDefinedBy:
        if pset.is_a('IfcRelDefinesByProperties'):
            ps = pset.RelatingPropertyDefinition
            if ps.is_a('IfcPropertySet'):
                for p in ps.HasProperties:
                    if hasattr(p, 'NominalValue'):
                        ps_dict[p.Name] = p.NominalValue.wrappedValue
    print(f'{px.Name:10s} {px.ObjectType} coords={coords[0] if coords else None} props={ps_dict}')

print('\n=== WALLS (PARAPETS) ===')
for w in model.by_type('IfcWall'):
    coords = get_placement_coord(w)
    print(f'{w.Name:15s} {w.PredefinedType} coords={coords[0] if coords else None}')
"

